// Validates every message the popup sends to the main process.
// The renderer is sandboxed, but the main process still treats its input as untrusted.

import { ACCELERATOR_PATTERN } from '../shared/accelerator.js';
import { DEFAULT_SETTINGS } from './store.js';

export class IpcValidationError extends Error {}

const fail = (msg) => {
  throw new IpcValidationError(msg);
};

const isPlainObject = (v) => v !== null && typeof v === 'object' && Object.getPrototypeOf(v) === Object.prototype;

/** Clip ids are UUIDs generated by the store. */
export function clipId(value) {
  if (typeof value !== 'string' || !/^[0-9a-f-]{8,64}$/i.test(value)) fail('Invalid clip id');
  return value;
}

export function bool(value) {
  if (typeof value !== 'boolean') fail('Expected a boolean');
  return value;
}

/** Options for clip:select. */
export function selectOptions(value = {}) {
  if (!isPlainObject(value)) fail('Invalid select options');
  const out = {};
  for (const [k, v] of Object.entries(value)) {
    if (k !== 'paste') fail(`Unknown select option "${k}"`);
    out.paste = bool(v);
  }
  return out;
}

/** A settings patch: only known keys, each with the right type and a sane range. */
export function settingsPatch(value) {
  if (!isPlainObject(value)) fail('Settings must be an object');
  const out = {};
  for (const [key, v] of Object.entries(value)) {
    if (!(key in DEFAULT_SETTINGS)) fail(`Unknown setting "${key}"`);
    const expected = typeof DEFAULT_SETTINGS[key];
    if (typeof v !== expected) fail(`Setting "${key}" must be a ${expected}`);
    if (key === 'hotkey' && !ACCELERATOR_PATTERN.test(v)) fail('Invalid shortcut');
    if (key === 'historyLimit' && !(Number.isInteger(v) && v >= 10 && v <= 5000)) fail('History size must be 10–5000');
    if (key === 'maxClipLength' && !(Number.isInteger(v) && v > 0)) fail('Invalid max clip length');
    out[key] = v;
  }
  return out;
}
